import{_ as a,C as n,c as o,o as s,j as t,G as r,a8 as l,a as c}from"./chunks/framework.8HQ-OgOa.js";const w=JSON.parse('{"title":"Advanced Tips","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/advanced-tips.md","filePath":"en/guide/advanced-tips.md"}'),d={name:"en/guide/advanced-tips.md"};function h(p,e,u,g,m,f){const i=n("ArticleMetadata");return s(),o("div",null,[e[0]||(e[0]=t("h1",{id:"advanced-tips",tabindex:"-1"},[c("Advanced Tips "),t("a",{class:"header-anchor",href:"#advanced-tips","aria-label":'Permalink to "Advanced Tips"'},"​")],-1)),r(i),e[1]||(e[1]=l('<p>Master these advanced techniques to unleash the full potential of ICC-CE:</p><h2 id="shape-drawing-tips" tabindex="-1">Shape Drawing Tips <a class="header-anchor" href="#shape-drawing-tips" aria-label="Permalink to &quot;Shape Drawing Tips&quot;">​</a></h2><h3 id="perfect-straight-lines" tabindex="-1">Perfect Straight Lines <a class="header-anchor" href="#perfect-straight-lines" aria-label="Permalink to &quot;Perfect Straight Lines&quot;">​</a></h3><ol><li><p>Enable straight line correction (Settings → Canvas → Straight line correction)</p></li><li><p>Adjust sensitivity to match your drawing style:</p><ul><li>Low Sensitivity (0.05-0.3): Requires lines to be very close to straight.</li><li>Medium Sensitivity (0.3-1.0): Suitable for most users.</li><li>High Sensitivity (1.0-2.0): Even slightly curved lines will be corrected as straight.</li></ul></li><li><p>Maintain a steady speed when drawing; avoid drawing too fast or too slow.</p></li></ol><h3 id="precise-shapes" tabindex="-1">Precise Shapes <a class="header-anchor" href="#precise-shapes" aria-label="Permalink to &quot;Precise Shapes&quot;">​</a></h3><p>Use shape recognition to create precise figures:</p><ol><li>Enable shape recognition (Settings → Shape Recognition)</li><li>Choose the shape types to recognize (Rectangle, Triangle, Circle, etc.)</li><li>Draw close to the target shape, and the system will automatically optimize it.</li></ol><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>Try closing your strokes for the best recognition results. For example, when drawing a rectangle, ensure you end near the starting point.</p></div><h3 id="connecting-figures" tabindex="-1">Connecting Figures <a class="header-anchor" href="#connecting-figures" aria-label="Permalink to &quot;Connecting Figures&quot;">​</a></h3><p>Endpoint snapping helps create well-connected complex figures:</p><ol><li>Enable endpoint snapping (Settings → Canvas → Straight line endpoint snapping)</li><li>Adjust snap distance to control the snapping range.</li><li>Draw new lines starting or ending close to the endpoints of existing lines.</li></ol><h2 id="touch-gestures" tabindex="-1">Touch Gestures <a class="header-anchor" href="#touch-gestures" aria-label="Permalink to &quot;Touch Gestures&quot;">​</a></h2><p>ICC-CE supports multi-touch gestures to enhance interaction:</p><table tabindex="0"><thead><tr><th>Gesture</th><th>Action</th><th>Applicable Mode</th></tr></thead><tbody><tr><td>Two-finger pinch</td><td>Zoom drawing area</td><td>All modes</td></tr><tr><td>Two-finger rotate</td><td>Rotate selected content</td><td>Selection mode</td></tr><tr><td>Two-finger drag</td><td>Pan drawing area</td><td>All modes</td></tr><tr><td>Left/Right swipe</td><td>Next/Prev page (PowerPoint)</td><td>Presentation mode</td></tr></tbody></table><h3 id="customizing-gestures" tabindex="-1">Customizing Gestures <a class="header-anchor" href="#customizing-gestures" aria-label="Permalink to &quot;Customizing Gestures&quot;">​</a></h3><p>In Settings → Gestures, you can:</p><ul><li>Enable/Disable specific gestures</li><li>Adjust gesture sensitivity</li><li>Configure gesture behaviors under specific modes</li></ul><h2 id="powerpoint-enhancement-tips" tabindex="-1">PowerPoint Enhancement Tips <a class="header-anchor" href="#powerpoint-enhancement-tips" aria-label="Permalink to &quot;PowerPoint Enhancement Tips&quot;">​</a></h2><h3 id="presentation-navigation-optimization" tabindex="-1">Presentation Navigation Optimization <a class="header-anchor" href="#presentation-navigation-optimization" aria-label="Permalink to &quot;Presentation Navigation Optimization&quot;">​</a></h3><ol><li>Use customizable navigation buttons to quickly switch slides.</li><li>Adjust button position and transparency to avoid blocking content.</li><li>Enable slide preview to see upcoming content.</li></ol><h3 id="efficient-annotation" tabindex="-1">Efficient Annotation <a class="header-anchor" href="#efficient-annotation" aria-label="Permalink to &quot;Efficient Annotation&quot;">​</a></h3><ol><li>Use preset colors to quickly switch and highlight different concepts.</li><li>Utilize Whiteboard mode to explain complex concepts, then return to slides.</li><li>Use the &quot;Clear all annotations&quot; function to quickly reset the current slide.</li></ol><h2 id="automated-workflows" tabindex="-1">Automated Workflows <a class="header-anchor" href="#automated-workflows" aria-label="Permalink to &quot;Automated Workflows&quot;">​</a></h2><h3 id="smart-software-detection" tabindex="-1">Smart Software Detection <a class="header-anchor" href="#smart-software-detection" aria-label="Permalink to &quot;Smart Software Detection&quot;">​</a></h3><p>ICC-CE can detect and adapt to other educational software:</p><ol><li>Enable relevant options in Settings → Automation.</li><li>When specific software is detected, ICC-CE will automatically adjust its behavior.</li><li>Set auto-docking conditions to avoid interface conflicts.</li></ol><h3 id="content-management" tabindex="-1">Content Management <a class="header-anchor" href="#content-management" aria-label="Permalink to &quot;Content Management&quot;">​</a></h3><p>Configure auto-save strategies:</p><ol><li>Configure auto-save location (Settings → Automation → Auto-save location).</li><li>Set auto-cleanup options to manage historical files.</li><li>Enable date folders to organize screenshots and ink files.</li></ol><h2 id="performance-optimization" tabindex="-1">Performance Optimization <a class="header-anchor" href="#performance-optimization" aria-label="Permalink to &quot;Performance Optimization&quot;">​</a></h2><p>If you encounter performance issues during use:</p><ol><li>Adjust canvas clearing strategies to reduce memory usage.</li><li>Enable UI scaling on high-resolution screens.</li><li>Use non-transparent mode to boost drawing performance.</li><li>Regularly clean up auto-saved folders.</li></ol>',32))])}const v=a(d,[["render",h]]);export{w as __pageData,v as default};
